[standards/infrastructure/iac/STD-INFRA-IAC-008-testing.md#example-1-formation-with-mockprovider-aws--override-for-a-data-source]

#### Example 1: Formation with `mock_provider "aws" {}` Override for a Data Source

```hcl
# tests/unit.tftest.hcl — using override_data for an EKS data source

mock_provider "aws" {
  # Override the EKS cluster data source to return a mock cluster
  override_data {
    target = data.aws_eks_cluster.cluster
    values = {
      id       = "mmes-cms-dev-cluster"
      endpoint = "https://mock.eks.endpoint"
      name     = "mmes-cms-dev-cluster"
    }
  }
}

run "plan_succeeds" {
  command = plan
  variables {
    product_abr      = "mmes-cms"
    environment      = "dev"
    eks_cluster_name = "mmes-cms-dev-cluster"
    vpc_id           = "vpc-00000000000000001"
    private_subnet_ids = ["subnet-00000000000000001", "subnet-00000000000000002"]
  }
}
```
